#include <iostream>
#include <string>
#include <unordered_set>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 100) return 1;
    std::unordered_set<std::string> known;
    for (int i = 0; i < n; i++) {
        std::string word;
        if (!(std::cin >> word)) return 1;
        if (word.size() < 1 || word.size() > 20) return 1;
        known.insert(word);
    }
    int q = 0;
    if (!(std::cin >> q)) return 1;
    if (q < 1 || q > 100) return 1;
    for (int i = 0; i < q; i++) {
        std::string query;
        if (!(std::cin >> query)) return 1;
        if (query.size() < 1 || query.size() > 20) return 1;
        std::cout << (known.count(query) ? "yes" : "no") << "\n";
    }
    return 0;
}
